'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const js=v=>esc(JSON.stringify(String(v)));
const arr=v=>Array.isArray(v)?v:[];
const num=v=>Number.isFinite(Number(v))?Number(v):0;
const fmt=v=>Number(v).toLocaleString('en-US');
const loc=k=>CATALOG.locs[k]||k||'';
const skillNames={0:'Basic Attack',1:'Special Attack',2:'Dodge',3:'Chain / Ultimate',5:'Core Skill',6:'Assist'};
const servers={prod_gf_jp:'Asia',prod_gf_us:'America',prod_gf_eu:'Europe',prod_gf_sg:'TW / HK / MO'};
const bannerNames={GACHA_TYPE_PERMANENT:'Stable Channel',GACHA_TYPE_CHARACTER_UP:'Exclusive Channel',GACHA_TYPE_WEAPON_UP:'W-Engine Channel',GACHA_TYPE_BANGBOO:'Bangboo Channel',GACHA_TYPE_CHARACTER_RETURN:'Exclusive Rescreening',GACHA_TYPE_WEAPON_RETURN:'W-Engine Reverberation'};
const TABS=['Today','Agents','Teams','Challenges','Calendar','Earnings','Signals'];
let state={uid:'',server:'prod_gf_jp',session:'disconnected',sections:{}},local={teams:[],snapshots:{},goals:{},challengeHistory:[],monthlyHistory:{}},tab='Today',agentFilter='',agentRole='all',library=false,modalAgent=null,agentPage='Build',challengeMode='shiyu',challengePrevious=false,calendarMode='Events',pullType='GACHA_TYPE_CHARACTER_UP',selection=-1,compareId=null;
function native(name,...args){if(['account','disconnect','pulls'].includes(name)&&state.connection==='syncing'){toast('Please wait for this account sync to finish');return false;}if(window.Eridu&&typeof Eridu[name]==='function'){Eridu[name](...args);return true;}toast('Available in the installed Thor app');return false;}
function save(){native('save',JSON.stringify(local));}
function restoreLocal(raw){try{const v=JSON.parse(raw);local={teams:[],snapshots:{},goals:{},challengeHistory:[],monthlyHistory:{},...v};}catch(e){}render();}
function data(key){return state.sections?.[key]?.data;}
function section(key){return state.sections?.[key]||{state:'waiting'};}
function connected(){return state.session==='connected';}
function publicAgents(){return arr(data('showcase')?.PlayerInfo?.ShowcaseDetail?.AvatarList);}
function ownedAgents(){const roster=arr(data('roster')?.avatar_list);return roster.length?roster:publicAgents();}
function aid(a){return String(a?.id??a?.Id??'');}
function catalog(id){return CATALOG.avatars[String(id)]||{};}
function nameOf(a){return a?.name_mi18n||a?.full_name_mi18n||loc(catalog(aid(a)).Name)||'Agent '+aid(a);}
function agentById(id){return ownedAgents().find(a=>aid(a)===String(id))||{Id:Number(id)};}
function art(a){const c=catalog(aid(a)),skin=c.Skins?.[a.SkinId];return skin?.CircleIcon||c.CircleIcon||a.role_square_url||a.hollow_icon_path||'';}
function imageUrl(path){if(!path)return '';if(path.startsWith('/ui/zzz/IconRole'))return 'art/'+path.split('/').pop().replace('.png','.webp');if(path.startsWith('/ui/zzz/'))return 'gear/'+path.split('/').pop().replace('.png','.webp');try{const u=new URL(path);if(u.protocol==='https:'&&['enka.network','act-webstatic.hoyoverse.com','upload-os-bbs.hoyolab.com','act-webstatic.hoyolab.com'].includes(u.hostname))return u.href;}catch(e){}return '';}
function img(path,cls='portrait'){const u=imageUrl(path);return u?`<img class="${cls}" src="${esc(u)}" alt="" loading="lazy" onerror="this.style.visibility='hidden'">`:'';}
function roleOf(a){return catalog(aid(a)).ProfessionType||({1:'Attack',2:'Stun',3:'Anomaly',4:'Support',5:'Defense',6:'Rupture',7:'Armorer'}[a.avatar_profession])||'Agent';}
function elementOf(a){return arr(catalog(aid(a)).ElementTypes).map(x=>({Elec:'Electric',Physics:'Physical'}[x]||x)).join(' / ')||({200:'Physical',201:'Fire',202:'Ice',203:'Electric',204:'Wind',205:'Ether',300:'Lumiflux'}[a.element_type])||'';}
function level(a){return a.level??a.Level??'—';}
function mindscape(a){return a.rank??a.TalentLevel??0;}
function when(t){if(!t)return 'Not synced';const date=new Date(num(t)<1e12?num(t)*1000:num(t));return Number.isNaN(+date)?'—':date.toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function age(t){if(!t)return 'Not synced';const s=Math.max(0,Math.floor((Date.now()-t)/1000));return s<60?'Just synced':s<3600?Math.floor(s/60)+'m ago':s<86400?Math.floor(s/3600)+'h ago':Math.floor(s/86400)+'d ago';}
function duration(s){s=Math.max(0,Math.floor(num(s)));return s>=86400?Math.floor(s/86400)+'d '+Math.floor(s%86400/3600)+'h':s>=3600?Math.floor(s/3600)+'h '+Math.floor(s%3600/60)+'m':Math.floor(s/60)+'m '+s%60+'s';}
function meter(current,max){return `<div class="meter"><i style="width:${Math.max(0,Math.min(100,num(current)/Math.max(1,num(max))*100))}%"></i></div>`;}
function button(label,call,primary=false){return `<button${primary?' class="primary"':''} onclick="${call}">${label}</button>`;}
function empty(title,text,action=''){return `<div class="empty"><strong>${esc(title)}</strong><p>${esc(text)}</p>${action}</div>`;}
function rich(text){return esc(text).replace(/&lt;[^&]*?&gt;/g,'').replace(/\\n/g,'<br>').replace(/\n/g,'<br>');}
function sectionMessage(key){const s=section(key);let out='';if(s.state==='loading')out+=`<div class="connection-note"><span class="spinner" style="width:10px;height:10px"></span> Refreshing ${esc(key.split(':')[0])}…</div>`;if(s.error)out+=`<div class="error">${esc(s.error)} ${button('Retry','refreshNow()')}</div>`;if(s.data&&(s.state==='cached'||s.state==='error'||Date.now()-s.at>600000))out+=`<div class="saved-hint">Saved information · ${when(s.at)}</div>`;return out;}
function locked(key,title){const s=section(key);if(s.data)return '';if(s.state==='loading')return '<div class="loading"><span class="spinner"></span>Loading '+esc(title)+'…</div>';if(s.error)return sectionMessage(key);return empty('Connect your HoYoLAB account',title+' becomes available after sign-in and account validation.',button('Connect HoYoLAB','native(\'login\')',true));}
function receive(next){state=next;state.sections=state.sections||{};const earnings=data('earnings');if(earnings?.data_month){local.monthlyHistory[earnings.data_month]=earnings.month_data;}
 let changed=false;if(earnings?.data_month)changed=true;for(const key of ['shiyu','assault','annihilation','threshold','lostvoid']){const s=section(key);if(s.state!=='ready'||!s.data)continue;const signature=JSON.stringify(s.data);const previous=local.challengeHistory.filter(x=>x.key===key).at(-1);if(!previous||previous.signature!==signature){local.challengeHistory.push({key,at:s.at,data:s.data,signature});changed=true;}}
 if(local.challengeHistory.length>120)local.challengeHistory=local.challengeHistory.slice(-120);if(changed)save();render();if(modalAgent&&$('#modal').open){const signature=JSON.stringify([data('agent:'+modalAgent),data('guide:'+modalAgent)]);if(signature!==window.agentDataSignature){window.agentDataSignature=signature;renderAgentModal();}}}
function render(){renderHeader();$('#nav').innerHTML=TABS.map(t=>`<button class="${tab===t?'active':''}" onclick="setTab(${js(t)})">${t}</button>`).join('');const main=$('#content');const top=main.scrollTop;main.className=tab==='Today'?'today':'';
 main.innerHTML=({Today:renderToday,Agents:renderAgents,Teams:renderTeams,Challenges:renderChallenges,Calendar:renderCalendar,Earnings:renderEarnings,Signals:renderSignals}[tab])();main.scrollTop=top;}
function renderHeader(){const p=data('showcase')?.PlayerInfo?.SocialDetail?.ProfileDetail;let label=state.session==='connected'?'HoYoLAB connected':state.session==='checking'?'Validating account…':state.session==='expired'?'Sign in again':state.session==='offline'?'Account offline':state.session==='choose-account'?'Choose account':p?'Showcase connected':'Connect account';if(state.connection==='syncing'&&state.session!=='checking')label='Syncing account…';$('#connection').innerHTML=`<i class="dot ${state.connection==='syncing'?'syncing':state.session==='expired'||state.session==='offline'?state.session:state.session==='connected'||p?'connected':state.session}"></i><span>${label}</span>`;
 $('#freshness').textContent=p?`${p.Nickname} · ${age(section('showcase').at)}`:'Preparing your account';const note=state.session==='expired'?'Your HoYoLAB session expired. Saved information is shown until you reconnect.':state.session==='choose-account'?'Signed in. Select a ZZZ profile in Account to finish connecting.':state.session==='offline'?'Unable to validate HoYoLAB. Saved information may be out of date.':'';$('#notice').hidden=!note;$('#notice').textContent=note;}
function setTab(t){tab=t;selection=-1;$('#content').scrollTop=0;render();}
function cycleTab(d){if($('#modal').open)return;setTab(TABS[(TABS.indexOf(tab)+d+TABS.length)%TABS.length]);}
function refreshNow(){if(state.connection==='syncing'){toast('Account sync is already running');return;}native('refresh');}
function taskCell(title,detail,value,done){return `<div class="panel task"><span class="check">${done?'✓':'○'}</span><div><h3>${esc(title)}</h3><p>${esc(detail)}</p></div>${value!==undefined?`<span class="progress ${done?'good':''}">${esc(value)}</span>`:''}</div>`;}
function renderToday(){const p=data('showcase')?.PlayerInfo?.SocialDetail?.ProfileDetail,n=data('notes');if(!n){return `<div class="account-hero"><div class="eyebrow">${p?'WELCOME BACK, '+esc(p.Nickname.toUpperCase()):'YOUR SECOND SCREEN IN NEW ERIDU'}</div><h2>${p?'Your agents are ready.':'A terminal for your next commission.'}</h2><p>${p?'Your public showcase is connected. Sign in to HoYoLAB for Battery Charge, daily tasks, events, earnings, and battle records.':'Preparing your profile and personal companion. Connect HoYoLAB to bring your account into view.'}</p><div class="actions">${button('Connect HoYoLAB',"native('login')",true)}${button('View agents',"setTab('Agents')")}</div></div>${sectionMessage('showcase')}${sectionMessage('notes')}<div class="grid"><div class="panel"><div class="eyebrow">PUBLIC PROFILE</div><div class="amount">${p?esc(p.Level):'—'}</div><div class="meta">Inter-Knot level</div></div><div class="panel"><div class="eyebrow">SHOWCASE</div><div class="amount">${publicAgents().length||'—'}</div><div class="meta">Agents with equipped builds</div></div></div><div class="banner">Account status refreshes independently of game loading. Open Account for connection steps and saved-data controls.</div>`;}
 const energy=n.energy||n.battery_charge||{},progress=energy.progress||energy,remaining=Math.max(0,num(energy.restore??energy.seconds_till_full)-(Date.now()-section('notes').at)/1000),v=n.vitality||n.engagement||{},w=n.weekly_task,b=n.hollow_zero?.bounty_commission||n.bounty_commission,h=n.hollow_zero?.survey_points||n.survey_points,store=n.video_store_state||n.vhs_sale?.sale_state,temple=n.temple_running||{};
 const full=num(progress.current)>=num(progress.max)&&num(progress.max)>0;
 return `<div class="row"><div><div class="eyebrow">${esc(p?.Nickname||'PROXY')} · ${esc(servers[state.server]||'')}</div><h2>Today in New Eridu</h2></div>${button('More','openDailyDetails()')}</div><div class="panel accent battery-panel"><div class="row"><div><div class="eyebrow">BATTERY CHARGE</div><div class="battery-value">${esc(progress.current??'—')}<small> / ${esc(progress.max??'—')}</small></div></div><div style="text-align:right"><div class="good small" id="battery-countdown" data-full="${Date.now()+remaining*1000}">${full?'Battery full':remaining?duration(remaining)+' Until Full':'Check game for current charge'}</div><div class="meta">${age(section('notes').at)} · HoYoLAB snapshot</div></div><div class="battery-icon">ϟ</div></div>${meter(progress.current,progress.max)}</div><div class="today-grid">${taskCell('Daily activity','Engagement',v.current===undefined?'—':v.current+' / '+v.max,num(v.current)>=num(v.max)&&num(v.max)>0)}${taskCell('Scratch card','Howl’s newsstand',n.card_sign==='CardSignDone'?'Done':'Available',n.card_sign==='CardSignDone')}${taskCell('Video store','Random Play',store==='SaleStateDone'?'Collect':store==='SaleStateDoing'?'Open':store==='SaleStateNo'?'Open store':'—',store==='SaleStateDoing')}${taskCell('Weekly tasks',w?'Resets in '+duration(w.refresh_time):'Not supplied',w?w.cur_point+' / '+w.max_point:'—',w&&num(w.cur_point)>=num(w.max_point))}${taskCell('Hollow Zero',b?'Bounty commissions':h?'Investigation points':'Not supplied',b?b.num+' / '+b.total:h?h.num+' / '+h.total:'—',b&&num(b.num)>=num(b.total))}${taskCell('Bangboo expedition','Suibian Temple',temple.expedition_state==='ExpeditionStateEnd'?'Returned':temple.expedition_state==='ExpeditionStateInProgress'?'Exploring':temple.expedition_state==='ExpeditionStateInCanSend'?'Dispatch':'—',temple.expedition_state==='ExpeditionStateInProgress')}</div><div class="row meta"><span>${section('notes').error?esc(section('notes').error):'Updated '+when(section('notes').at)}</span>${button(state.reminders?'Reminders on':'Enable reminders',`native('reminders',${!state.reminders})`)}</div>`;
}
function openDailyDetails(){const n=data('notes')||{},t=n.temple_running||{},h=n.hollow_zero||{},b=h.bounty_commission||n.bounty_commission,p=h.survey_points||n.survey_points,m=n.member_card||{},auto=t.auto_work;const rows=[['Crafting',scalar(t.bench_state)],['Temple shop',scalar(t.shelve_state)],['Bangboo expedition',scalar(t.expedition_state)],['Temple level',t.level??'—'],['Weekly Temple currency',t.current_currency===undefined?'—':fmt(t.current_currency)+' / '+fmt(t.weekly_currency_max)],['Temple currency reset',t.currency_next_refresh_ts?duration(t.currency_next_refresh_ts):'—'],['Auto-work',!auto?'Not supplied':auto.auto_work_ended?'Ready to collect':auto.is_auto_work_running?'Running · '+duration(auto.left_ts):'Idle'],['Hollow Zero bounties',b?b.num+' / '+b.total:'Not supplied'],['Investigation points',p?p.num+' / '+p.total:'Not supplied'],['Inter-Knot Membership',m.is_open?'Active · '+duration(m.exp_time)+' remaining':'Inactive'],['Membership reward',n.card_sign==='CardSignDone'?'Collected':'Check in game']];modal('Daily & weekly status',`${sectionMessage('notes')}<div class="panel"><h3>Management & collection</h3>${rows.map(([title,value])=>`<div class="property"><span>${esc(title)}</span><b>${esc(value)}</b></div>`).join('')}</div><div class="banner">Battery countdown is an estimate from the latest snapshot. Reminders use the last synced data and can arrive late under Android power saving.</div>`);} 
function renderAgents(){if(agentKind==='Bangboo')return renderBangboos();let agents=library?Object.keys(CATALOG.avatars).map(id=>ownedAgents().find(a=>aid(a)===id)||{Id:Number(id)}):ownedAgents();agents=agents.filter(a=>(!agentFilter||nameOf(a).toLowerCase().includes(agentFilter.toLowerCase()))&&(agentRole==='all'||roleOf(a)===agentRole));return `<div class="row section-head"><div><h2>${library?'Agent library':'Your agents'}</h2><p class="meta">${library?'Bundled catalog · '+Object.keys(CATALOG.avatars).length+' agents':data('roster')?'HoYoLAB roster':'Public showcase · '+publicAgents().length+' agents'}</p></div>${button(library?'My roster':'All agents',`library=${!library};render()`)}</div><div class="toolbar"><input aria-label="Search agents" placeholder="Search agents…" value="${esc(agentFilter)}" oninput="agentFilter=this.value;filterAgents()"><select aria-label="Agent specialty" onchange="agentRole=this.value;render()"><option value="all">All specialties</option>${['Attack','Stun','Anomaly','Support','Defense','Rupture','Armorer'].map(r=>`<option ${r===agentRole?'selected':''}>${r}</option>`).join('')}</select></div><div class="chips">${button('Agents',"agentKind='Agents';render()",true)}${button('Bangboo',"agentKind='Bangboo';render()")}</div><div id="agent-results">${agentsGrid(agents)}</div>${sectionMessage(data('roster')?'roster':'showcase')}${!data('roster')?'<p class="saved-hint">Showcase access includes displayed agents and equipped gear. Connect HoYoLAB to load your owned roster.</p>':''}`;}
function agentsGrid(agents){return agents.length?`<div class="grid">${agents.map(a=>`<button class="card agent" onclick="openAgent(${js(aid(a))})">${img(art(a))}<div class="copy"><h3>${esc(nameOf(a))}</h3><div class="meta">${esc(elementOf(a))} · ${esc(roleOf(a))}</div><div class="meta">${level(a)==='—'?'Catalog entry':'Lv. '+esc(level(a))+' · M'+mindscape(a)}</div></div><span class="rank">${(a.rarity||catalog(aid(a)).Rarity===4)?(a.rarity||'S'):'A'}</span></button>`).join('')}</div>`:empty('No matching agents','Try a different search or connect your account.');}
function filterAgents(){const input=$('input[aria-label="Search agents"]'),pos=input.selectionStart;render();const next=$('input[aria-label="Search agents"]');next.focus();next.setSelectionRange(pos,pos);}
function fullAgent(id){return arr(data('agent:'+id)?.avatar_list)[0]||publicAgents().find(a=>aid(a)===String(id))||agentById(id);}
function normalized(a){if(a.Id!==undefined){const c=catalog(a.Id);return {id:String(a.Id),name:nameOf(a),level:a.Level,rank:a.TalentLevel,weapon:a.Weapon,discs:arr(a.EquippedList).map(d=>({...d.Equipment,slot:d.Slot})),skills:arr(a.SkillLevelList).map(s=>({skill_type:s.Index,level:s.Level+(s.Index===5?0:(a.TalentLevel>=3?2:0)+(a.TalentLevel>=5?2:0))})),properties:[],source:'Enka showcase',raw:a};}return {id:String(a.id),name:nameOf(a),level:a.level,rank:a.rank,weapon:a.weapon,discs:arr(a.equip),skills:arr(a.skills),properties:arr(a.properties),source:'HoYoLAB',raw:a};}
function openAgent(id){modalAgent=String(id);agentPage='Build';modal(nameOf(agentById(id)),'');renderAgentModal();if(connected()&&!data('agent:'+id)&&section('agent:'+id).state!=='loading')native('agent',String(id));}
function renderAgentModal(){if(!modalAgent)return;const a=normalized(fullAgent(modalAgent)),raw=a.raw;$('#modal-title').textContent=a.name;$('#modal-body').innerHTML=`<div class="agent-head">${img(art(raw))}<div><h2>${esc(a.name)}</h2><p class="small">${esc(elementOf(raw))} · ${esc(roleOf(raw))}</p><span class="badge">${a.level===undefined?'Catalog':'Lv. '+esc(a.level)+' · Mindscape '+esc(a.rank)}</span><p class="meta">${a.level===undefined?'Connect to load owned build':a.source}</p></div></div><div class="modal-tabs">${['Build','Skills','Upgrade','History'].map(t=>button(t,`agentPage=${js(t)};renderAgentModal()`,agentPage===t)).join('')}</div>${sectionMessage('agent:'+modalAgent)}${({Build:()=>renderBuild(a),Skills:()=>renderSkills(a),Upgrade:()=>renderUpgrade(a),History:()=>renderBuildHistory(a)}[agentPage])()}`;}
function propertyLabel(p){return p.property_name||loc(CATALOG.property[String(p.PropertyId??p.property_id)]?.Name)||'Stat '+(p.PropertyId??p.property_id);}
function propertyValue(p,{main=false,level=0,rarity=4}={}){if(p.base!==undefined)return String(p.base);const percent=CATALOG.property[String(p.PropertyId)]?.Format?.includes('%');let value=num(p.PropertyValue);if(main)value*=1+num(level)*({4:.2,3:.25,2:.3}[rarity]||.2);else value*=Math.max(1,num(p.PropertyLevel));return percent?(value/100).toFixed(1).replace(/\.0$/,'')+'%':fmt(Math.floor(value));}
function propertyRows(properties,opts={}){return arr(properties).map(p=>`<div class="property ${opts.main?'main':''}"><span>${esc(propertyLabel(p))}</span><b>${esc(p.final??propertyValue(p,opts))}</b></div>`).join('');}
function weaponName(w){return w?.name||loc(CATALOG.weapons[String(w?.Id)]?.ItemName)||'W-Engine';}
function weaponCard(w){if(!w)return empty('No W-Engine data','Load this agent’s details to see their equipped W-Engine.');const cat=CATALOG.weapons[String(w.Id)]||{};return `<div class="panel"><div class="list-row">${img(w.icon||cat.ImagePath,'icon')}<div><h3>${esc(weaponName(w))}</h3><div class="meta">Lv. ${esc(w.level??w.Level)} · Phase ${esc(w.star??w.UpgradeLevel??'—')}</div></div>${button('Compare',`compareEquipment('weapon')`)}</div>${propertyRows(w.main_properties,{main:true})}${propertyRows(w.properties)}${w.talent_content?`<p class="rich">${rich(w.talent_content)}</p>`:'<p class="saved-hint">Showcase supplies equipment level and phase. Load HoYoLAB details for final W-Engine stats and effects.</p>'}</div>`;}
function discModel(d){if(d.Id!==undefined){const cat=CATALOG.equipments.Items?.[String(d.Id)]||{},suit=CATALOG.equipments.Suits?.[String(cat.SuitId)]||{};return {id:d.Id,uid:d.Uid,slot:d.slot,level:d.Level,rarity:cat.Rarity||4,name:loc(suit.Name)||'Drive Disc',icon:suit.Icon,main:d.MainPropertyList||d.MainStatList,sub:d.RandomPropertyList,enka:true};}return {id:d.id,uid:null,slot:d.equipment_type,level:d.level,rarity:d.rarity==='S'?4:d.rarity==='A'?3:2,name:d.name,icon:d.icon,main:d.main_properties,sub:d.properties,enka:false};}
function renderBuild(a){return `${a.properties.length?'<div class="stats">'+a.properties.map(p=>`<div class="stat"><b>${esc(p.final||p.base)}</b><span>${esc(p.property_name)}</span></div>`).join('')+'</div><div class="divider"></div>':''}${weaponCard(a.weapon)}<div class="row section-head" style="margin-top:12px"><h3>Drive Discs</h3><span class="meta">${a.discs.length} / 6 supplied</span></div><div class="disc-grid">${a.discs.map(d=>{const m=discModel(d);return `<div class="disc"><div class="row"><h3>${esc(m.slot)} · ${esc(m.name)}</h3><span class="badge">+${m.level}</span></div>${propertyRows(m.main,{main:true,level:m.level,rarity:m.rarity})}<div class="divider"></div>${propertyRows(m.sub)}<div class="actions">${button('Compare',`compareEquipment('disc',${num(m.slot)})`)}</div></div>`;}).join('')}</div>${a.discs.some(d=>d.Id!==undefined)?'<p class="saved-hint">Enka disc main stats use the documented rarity/level approximation; substats use recorded rolls. HoYoLAB details supply formatted values.</p>':''}${!a.discs.length?empty('Equipment not loaded','Connect HoYoLAB and load this agent to inspect equipped gear.'):''}<div class="actions">${button('Save build snapshot',`snapshotBuild(${js(a.id)})`,true)}${button('Refresh agent',`native('agent',${js(a.id)})`)}</div>`;}
function renderSkills(a){return a.skills.length?a.skills.map(s=>`<div class="panel" style="margin-bottom:8px"><div class="row"><h3>${esc(skillNames[s.skill_type]||'Skill')}</h3><span class="badge">Lv. ${esc(s.level)}</span></div>${arr(s.items).map(i=>`<div class="divider"></div><h3>${esc(i.title)}</h3><p class="rich">${rich(i.text)}</p>`).join('')}</div>`).join(''):empty('Skill details not loaded','Connect HoYoLAB to load skill descriptions.');}
function renderUpgrade(a){const id=a.id,g=arr(data('guide:'+id)?.list)[0],goal=local.goals[id]||{level:60,weapon:60,notes:''};let out=`<div class="panel"><h3>Upgrade targets</h3><p class="meta">Saved on your Thor for this agent.</p><div class="form-row"><div><label>Agent level</label><input id="goal-level" type="number" min="1" max="100" value="${esc(goal.level)}"></div><div><label>W-Engine level</label><input id="goal-weapon" type="number" min="1" max="100" value="${esc(goal.weapon)}"></div></div><label>Farming & build notes</label><textarea id="goal-notes" placeholder="Materials, target stats, next skill upgrade…">${esc(goal.notes)}</textarea><div class="actions">${button('Save targets',`saveGoal(${js(id)})`,true)}${button('Load HoYoLAB guide',`native('guide',${js(id)})`)}</div></div>${sectionMessage('guide:'+id)}`;
 const missing=[];if(a.level!==undefined&&num(a.level)<num(goal.level))missing.push(`Agent: ${a.level} → ${goal.level}`);const wl=a.weapon?.level??a.weapon?.Level;if(wl!==undefined&&num(wl)<num(goal.weapon))missing.push(`W-Engine: ${wl} → ${goal.weapon}`);for(const raw of a.discs){const d=discModel(raw),cap=({4:15,3:12,2:9})[d.rarity];if(d.level<cap)missing.push(`Disc ${d.slot}: +${d.level} → +${cap}`);}if(missing.length)out+=`<div class="panel" style="margin-top:8px"><h3>Next upgrades</h3>${missing.map(x=>`<div class="list-row small">${esc(x)}</div>`).join('')}</div>`;
 if(g){out+=`<div class="divider"></div><h3>${esc(g.plan?.name||'HoYoLAB upgrade recommendations')}</h3><p class="rich">${rich(g.plan?.desc||'')}</p>`;const plan=g.plan?.item;if(plan){out+=`<div class="panel"><h3>Target stats</h3>${arr(plan.avatar).map(s=>`<div class="property"><span>${esc(s.property_name)}</span><b>${esc(s.low)} – ${esc(s.high)}</b></div>`).join('')}</div>`;for(const which of ['main','backup']){const w=plan.weapon?.[which];if(w?.id)out+=`<div class="divider"></div><div class="meta">${which==='main'?'Recommended':'Alternative'} W-Engine</div>${weaponCard(w)}`;}if(plan.equip)out+=inspect(plan.equip,'Recommended Drive Discs',0,true);if(g.avatar?.skill_upgrade)out+=inspect(g.avatar.skill_upgrade,'Skill priorities',0,true);if(plan.team)out+=renderRecommendedTeams(plan.team);}
 out+=inspect(g,'Full upgrade guide',0,false);}
 return out;}
function saveGoal(id){local.goals[id]={level:Math.max(1,Math.min(100,num($('#goal-level').value))),weapon:Math.max(1,Math.min(100,num($('#goal-weapon').value))),notes:$('#goal-notes').value.slice(0,6000)};save();toast('Upgrade targets saved');renderAgentModal();}
function snapshotBuild(id){const a=normalized(fullAgent(id));if(a.level===undefined){toast('Load an owned build first');return;}const list=local.snapshots[id]||[];list.push({at:Date.now(),build:a});local.snapshots[id]=list.slice(-30);save();toast('Build snapshot saved');}
function renderBuildHistory(a){const list=local.snapshots[a.id]||[];return `${button('Save current build',`snapshotBuild(${js(a.id)});renderAgentModal()`,true)}<div class="divider"></div>${list.length?list.slice().reverse().map((s,i)=>`<div class="list-row"><div><h3>${when(s.at)}</h3><p class="meta">Lv. ${esc(s.build.level)} · M${esc(s.build.rank)} · ${esc(weaponName(s.build.weapon))}</p></div>${button('Compare',`compareSnapshot(${js(a.id)},${list.length-i-1})`)}</div>`).join(''):empty('No build snapshots yet','Save a build to compare future upgrades.')}`;}
function compareSnapshot(id,index){const now=normalized(fullAgent(id)),old=local.snapshots[id][index].build;modalAgent=null;modal('Build comparison',`<p class="meta">Saved ${when(local.snapshots[id][index].at)} → current snapshot</p><div class="compare"><b>Stat</b><b>Saved</b><b>Current</b></div>${[['Agent level',old.level,now.level],['Mindscape',old.rank,now.rank],['W-Engine',weaponName(old.weapon),weaponName(now.weapon)],['W-Engine level',old.weapon?.level??old.weapon?.Level,now.weapon?.level??now.weapon?.Level],...now.properties.map(p=>[p.property_name,old.properties.find(o=>o.property_id===p.property_id)?.final??'—',p.final])].map(r=>`<div class="compare">${r.map(v=>`<span>${esc(v??'—')}</span>`).join('')}</div>`).join('')}<div class="divider"></div><h3>Drive Discs</h3>${now.discs.map(raw=>{const d=discModel(raw),o=old.discs.map(discModel).find(x=>x.slot===d.slot);return `<div class="compare"><span>Slot ${d.slot}</span><span>${esc(o?.name||'—')} +${o?.level??'—'}</span><span>${esc(d.name)} +${d.level}</span></div>`;}).join('')}`);}
function compareEquipment(type,slot){const source=normalized(fullAgent(modalAgent||compareId));compareId=source.id;const options=ownedAgents().filter(a=>aid(a)!==source.id);modalAgent=null;modal(type==='weapon'?'Compare W-Engines':'Compare Drive Disc '+slot,`<div class="meta">Equipped on ${esc(source.name)}</div><select id="compare-agent" onchange="renderEquipmentComparison(${js(type)},${num(slot)},${js(source.id)})"><option value="">Choose another agent…</option>${options.map(a=>`<option value="${esc(aid(a))}">${esc(nameOf(a))}</option>`).join('')}</select><div id="equipment-comparison"></div><p class="saved-hint">Compares supplied equipment stats. Team buffs and conditional combat effects are not simulated.</p>`);}
function renderEquipmentComparison(type,slot,id){const targetId=$('#compare-agent').value;if(!targetId)return;const a=normalized(fullAgent(id)),b=normalized(fullAgent(targetId));let wa=type==='weapon'?a.weapon:a.discs.map(discModel).find(d=>d.slot===slot),wb=type==='weapon'?b.weapon:b.discs.map(discModel).find(d=>d.slot===slot);const root=$('#equipment-comparison');if(!wa||!wb){root.innerHTML=empty('Equipment details needed','Load the other agent’s build, then compare again.',button('Load build',`native('agent',${js(targetId)})`));return;}const rows=type==='weapon'?[['Name',weaponName(wa),weaponName(wb)],['Level',wa.level??wa.Level,wb.level??wb.Level],['Phase',wa.star??wa.UpgradeLevel,wb.star??wb.UpgradeLevel]]:[['Set',wa.name,wb.name],['Level',wa.level,wb.level],...Array.from(new Set([...arr(wa.main),...arr(wa.sub),...arr(wb.main),...arr(wb.sub)].map(propertyLabel))).map(label=>[label,...[wa,wb].map(d=>{const p=[...arr(d.main),...arr(d.sub)].find(p=>propertyLabel(p)===label);return p?propertyValue(p,{main:arr(d.main).includes(p),level:d.level,rarity:d.rarity}):'—';})])];if(type==='weapon'){const props=w=>[...arr(w.main_properties),...arr(w.properties)];for(const label of new Set([...props(wa),...props(wb)].map(propertyLabel)))rows.push([label,...[wa,wb].map(w=>{const p=props(w).find(p=>propertyLabel(p)===label);return p?p.base:'—';})]);}root.innerHTML=`<div class="compare"><b>Equipment</b><b>${esc(a.name)}</b><b>${esc(b.name)}</b></div>${rows.map(r=>`<div class="compare">${r.map(v=>`<span>${esc(v??'—')}</span>`).join('')}</div>`).join('')}`;}
function renderTeams(){return `<div class="row section-head"><div><h2>Your squads</h2><p class="meta">Saved teams, rotations, boss notes & build targets</p></div>${button('New squad','editTeam(-1)',true)}</div>${local.teams.length?local.teams.map((t,i)=>`<div class="panel" style="margin-bottom:8px"><div class="row"><h3>${esc(t.name)}</h3><span class="badge">${t.active?'Pinned squad':esc(t.mode||'General')}</span></div><div class="team-slots">${arr(t.agents).map(id=>{const a=agentById(id);return `<button class="team-slot" onclick="openAgent(${js(id)})">${img(art(a))}<strong>${esc(nameOf(a))}</strong><div class="meta">${esc(roleOf(a))}</div></button>`;}).join('')}</div>${t.bangboo?`<p class="small">Bangboo · ${esc(t.bangboo)}</p>`:''}${t.rotation?`<div class="banner"><strong>Rotation</strong><p style="white-space:pre-line">${esc(t.rotation)}</p></div>`:''}${t.notes?`<p class="rich">${esc(t.notes)}</p>`:''}<div class="actions">${button('Edit',`editTeam(${i})`)}${button(t.active?'Pinned':'Pin squad',`pinTeam(${i})`)}${button('Upgrade checklist',`teamUpgrades(${i})`)}</div></div>`).join(''):empty('Build your first squad','Pick three agents, a Bangboo, and keep your rotation visible during play.',button('Create squad','editTeam(-1)',true))}`;}
function editTeam(index){const t=local.teams[index]||{name:'',agents:[],rotation:'',notes:'',bangboo:'',mode:'General'};const agents=ownedAgents();const boos=arr(data('bangboos')?.list);modal('Squad setup',`<label>Squad name</label><input id="team-name" value="${esc(t.name)}" placeholder="e.g. Shiyu · Team 1"><div class="team-slots">${[0,1,2].map(i=>`<div><label>Agent ${i+1}</label><select id="team-agent-${i}"><option value="">Choose agent</option>${agents.map(a=>`<option value="${esc(aid(a))}" ${String(t.agents[i])===aid(a)?'selected':''}>${esc(nameOf(a))}</option>`).join('')}</select></div>`).join('')}</div><div class="form-row"><div><label>Bangboo</label><input id="team-bangboo" list="bangboo-options" value="${esc(t.bangboo)}" placeholder="Bangboo name"><datalist id="bangboo-options">${boos.map(b=>`<option>${esc(b.name||b.name_mi18n||b.id)}</option>`).join('')}</datalist></div><div><label>Mode / boss</label><input id="team-mode" value="${esc(t.mode)}"></div></div><label>Rotation</label><textarea id="team-rotation" placeholder="Opener → stun setup → support buff → damage window">${esc(t.rotation)}</textarea><label>Boss & encounter notes</label><textarea id="team-notes" placeholder="Weaknesses, counters, attack reminders…">${esc(t.notes)}</textarea><div class="actions">${button('Save squad',`saveTeam(${index})`,true)}${index>=0?button('Delete squad',`deleteTeam(${index})`):''}</div>`);}
function saveTeam(index){const agents=[0,1,2].map(i=>$('#team-agent-'+i).value);if(agents.some(x=>!x)||new Set(agents).size!==3){toast('Choose three different agents');return;}const t={name:$('#team-name').value.trim()||'New squad',agents,bangboo:$('#team-bangboo').value,mode:$('#team-mode').value,rotation:$('#team-rotation').value,notes:$('#team-notes').value,active:local.teams[index]?.active||false};if(index<0)local.teams.push(t);else local.teams[index]=t;save();closeModal();render();toast('Squad saved');}
function deleteTeam(index){local.teams.splice(index,1);save();closeModal();render();}
function pinTeam(index){local.teams.forEach((t,i)=>t.active=i===index);save();render();}
function teamUpgrades(index){const team=local.teams[index];modal('Squad upgrade checklist',team.agents.map(id=>{const a=normalized(fullAgent(id)),g=local.goals[id]||{level:60,weapon:60};return `<div class="panel"><h3>${esc(a.name)}</h3><div class="property"><span>Agent level</span><b>${esc(a.level??'—')} / ${g.level}</b></div><div class="property"><span>W-Engine</span><b>${esc(a.weapon?.level??a.weapon?.Level??'—')} / ${g.weapon}</b></div><p class="rich">${esc(g.notes||'No farming notes yet.')}</p>${button('Open upgrades',`openAgent(${js(id)});agentPage='Upgrade';renderAgentModal()`)}</div>`;}).join(''));}
function renderRecommendedTeams(teams){return '<div class="divider"></div><h3>Recommended teams</h3>'+['main','backup'].map(which=>{const t=teams[which];if(!t)return '';const agents=arr(t.avatar_list);return `<div class="panel" style="margin-top:7px"><div class="meta">${which==='main'?'Primary':'Alternative'} · HoYoLAB guide</div><div class="chips">${agents.map(a=>`<span class="badge">${esc(nameOf(a))}${ownedAgents().some(o=>aid(o)===aid(a))?' ✓':''}</span>`).join('')}</div><p class="small">${arr(t.buddy_list).map(b=>esc(b.name)).join(' / ')}</p>${agents.length===3?button('Save as squad',`saveRecommended(${js(modalAgent)},${js(which)})`):''}</div>`;}).join('');}
function saveRecommended(id,which){const t=arr(data('guide:'+id)?.list)[0]?.plan?.item?.team?.[which];if(!t)return;local.teams.push({name:nameOf(agentById(id))+' · '+which,agents:arr(t.avatar_list).map(a=>String(a.id)),bangboo:t.buddy_list?.[0]?.name||'',rotation:'',notes:'Imported from HoYoLAB upgrade guide.',mode:'General',active:false});save();toast('Recommended squad saved');}
function renderChallenges(){const modes={shiyu:'Shiyu Defense',assault:'Deadly Assault',annihilation:'Annihilation',threshold:'Threshold',lostvoid:'Lost Void'};const key=challengeMode+(challengePrevious?':previous':''),s=section(key);return `<div class="section-head"><h2>Battle records</h2><p class="meta">Recorded results · build a history as you sync</p></div><div class="chips">${Object.entries(modes).map(([k,v])=>`<button class="${challengeMode===k?'on':''}" onclick="challengeMode=${js(k)};challengePrevious=false;render()">${v}</button>`).join('')}</div><div class="row"><h3>${modes[challengeMode]}</h3><div class="actions" style="margin:0">${button(challengePrevious?'Current cycle':'Previous cycle',`togglePrevious()`) }${button('History','showChallengeHistory()')}</div></div>${sectionMessage(key)}${s.data?`<div class="saved-hint">Synced ${when(s.at)}</div>${challengeSummary(s.data)}${renderBattleTeams(s.data)}${inspect(s.data,'Battle details',0,true)}`:locked(key,modes[challengeMode]+' records')}`;}
function togglePrevious(){if(['threshold','lostvoid'].includes(challengeMode)){toast('Use saved history to compare this mode');return;}challengePrevious=!challengePrevious;render();if(challengePrevious&&!data(challengeMode+':previous'))native('previous',challengeMode);}
function challengeSummary(d){const root=d.hadal_info_v2||d.hadal_info_v1||d.void_front_battle_detail?.void_front_battle_abstract_info_brief||d.void_front_battle_detail||d.void_front_battle_abstract_info_brief||d;const scores=[];for(const [key,label] of [['total_score','Total score'],['total_star','Stars'],['rating','Rating'],['max_layer','Highest layer'],['rank_percent','Rank percentile'],['total_challenge_times','Attempts']])if(root[key]!==undefined&&typeof root[key]!=='object')scores.push(`<div class="stat"><b>${esc(key==='rank_percent'?num(root[key])/100+'%':typeof root[key]==='number'?fmt(root[key]):root[key])}</b><span>${label}</span></div>`);return scores.length?`<div class="stats" style="margin:9px 0">${scores.join('')}</div>`:'';}
function renderBattleTeams(d){const found=[];function walk(v,depth=0){if(depth>8||!v||typeof v!=='object')return;if(Array.isArray(v)){v.forEach(x=>walk(x,depth+1));return;}for(const [k,a] of Object.entries(v)){if(['avatar_list','avatars','agents','characters','avatar_info_list'].includes(k)&&Array.isArray(a)&&a.length&&a.every(x=>x&&typeof x==='object'&&(x.id||x.avatar_id))){found.push({agents:a,score:v.score,clear:v.clear_time??v.cost_time,star:v.star});}else if(typeof a==='object')walk(a,depth+1);}}walk(d);return found.slice(0,16).map((t,i)=>`<div class="panel" style="margin-top:8px"><div class="row"><h3>Recorded team ${i+1}</h3><span class="badge">${t.score!==undefined?'Score '+fmt(t.score):t.clear!==undefined?'Clear '+t.clear+'s':t.star!==undefined?t.star+' stars':'Result team'}</span></div><div class="chips">${t.agents.map(a=>button(esc(nameOf({id:a.id??a.avatar_id,...a})),`openAgent(${js(a.id??a.avatar_id)})`)).join('')}</div></div>`).join('');}
function showChallengeHistory(){const list=local.challengeHistory.filter(x=>x.key===challengeMode).slice().reverse();modal('Saved battle history',list.length?list.map((x,i)=>`<details class="detail-group" ${i===0?'open':''}><summary>${when(x.at)}</summary>${challengeSummary(x.data)}${inspect(x.data,'Result details',0,false)}</details>`).join(''):empty('No saved results yet','Results are saved when a successful sync detects a change.'));}
function renderCalendar(){const key=calendarMode==='Events'?'events':'banners',d=data(key);const events=calendarMode==='Events'?arr(d?.activity_list):[...arr(d?.avatar_gacha_schedule_list),...arr(d?.weapon_gacha_schedule_list)];events.sort((a,b)=>num(a.end_ts)-num(b.end_ts));return `<div class="row section-head"><div><h2>New Eridu calendar</h2><p class="meta">Events, banners & ending-soon reminders</p></div>${button(state.reminders?'Reminders on':'Reminders',`native('reminders',${!state.reminders})`)}</div><div class="chips">${['Events','Banners'].map(x=>`<button class="${calendarMode===x?'on':''}" onclick="calendarMode=${js(x)};render()">${x}</button>`).join('')}</div>${sectionMessage(key)}${!d?locked(key,'Your event calendar'):events.length?events.map(e=>{const names=arr(e.avatar_list).map(a=>a.avatar_name||a.full_name).join(' / ')||arr(e.weapon_list).map(w=>loc(CATALOG.weapons[String(w.weapon_id)]?.ItemName)||w.weapon_id).join(' / ');const title=e.name||names||bannerNames[e.gacha_type]||'Signal Search';const end=num(e.end_ts)*1000,start=num(e.start_ts)*1000,finished=end<Date.now();return `<div class="panel" style="margin-bottom:8px"><div class="row"><h3>${esc(title)}</h3><span class="badge ${finished?'orange':''}">${finished?'Ended':start>Date.now()?'Upcoming':'Active'}</span></div><p class="meta" style="margin-top:5px">${e.gacha_type?esc(bannerNames[e.gacha_type]||e.gacha_type)+' · ':''}${when(start)} → ${when(end)}</p>${!finished?`<p class="small good" style="margin-top:7px">${start>Date.now()?'Starts in '+duration((start-Date.now())/1000):'Ends in '+duration((end-Date.now())/1000)}</p>`:''}${e.monochrome_cnt!==undefined?`<div class="property"><span>Event rewards collected</span><b>${esc(e.monochrome_got_cnt)} / ${esc(e.monochrome_cnt)}</b></div>${meter(e.monochrome_got_cnt,e.monochrome_cnt)}`:''}${arr(e.avatar_list).length?`<div class="chips">${e.avatar_list.map(a=>button(esc(a.avatar_name||a.full_name),`openAgent(${js(a.avatar_id)})`)).join('')}</div>`:''}</div>`;}).join(''):empty('No calendar entries supplied','Try refreshing after the next game update.')}`;}
function chart(items){const max=Math.max(1,...items.map(x=>num(x.value)));return `<div class="chart">${items.map(x=>`<div title="${esc(x.label)}: ${num(x.value)}"><b>${fmt(x.value)}</b><i style="height:${Math.max(2,num(x.value)/max*67)}px"></i><small>${esc(x.label)}</small></div>`).join('')}</div>`;}
function renderEarnings(){const d=data('earnings'),m=d?.month_data;return `<div class="row section-head"><div><h2>Inter-Knot earnings</h2><p class="meta">Monthly income & saved trends</p></div>${d?`<select aria-label="Income month" onchange="native('month',this.value)">${arr(d.optional_month).map(x=>`<option value="${esc(x)}" ${x===d.data_month?'selected':''}>${esc(x)}</option>`).join('')}</select>`:''}</div>${sectionMessage('earnings')}${!d?locked('earnings','Monthly earnings'):`<div class="grid three">${arr(m?.list).map(x=>`<div class="panel"><div class="amount">${fmt(x.count)}</div><div class="small">${esc(x.data_name||x.data_type)}</div><div class="actions">${button('Transactions',`openIncome(${js(d.data_month)},${js(x.data_type)},1)`)}</div></div>`).join('')}</div><div class="panel" style="margin-top:8px"><h3>Polychrome sources</h3>${chart(arr(m?.income_components).map(x=>({label:label(x.action),value:x.num})))}${arr(m?.income_components).map(x=>`<div class="property"><span>${esc(label(x.action))}</span><b>${fmt(x.num)} · ${num(x.percent)}%</b></div>`).join('')}</div><div class="panel" style="margin-top:8px"><h3>Monthly Polychrome trend</h3>${chart(Object.entries(local.monthlyHistory).sort(([a],[b])=>a.localeCompare(b)).slice(-8).map(([month,data])=>({label:month,value:arr(data?.list).find(x=>x.data_type==='PolychromesData')?.count||0})))}<p class="meta">Includes months you have synced on this companion.</p></div>`}`;}
let incomeRequest=null;let agentKind='Agents';
function openIncome(month,type,page){incomeRequest={month,type,page};modal('Earning transactions','<div id="income-transactions"><div class="loading"><span class="spinner"></span>Loading transactions…</div></div>');native('incomeDetail',month,type,page);}
function renderIncome(){const d=data('incomeDetail'),r=incomeRequest;if(!r||!$('#modal').open||!$('#income-transactions'))return;$('#income-transactions').innerHTML=sectionMessage('incomeDetail')+(d&&d.data_month===r.month&&d.data_type===r.type&&num(d.current_page)===r.page?`${arr(d.list).map(x=>`<div class="list-row"><div><h3>${esc(label(x.action))}</h3><p class="meta">${esc(x.time)}</p></div><strong class="good">+${fmt(x.num)}</strong></div>`).join('')}<div class="actions">${r.page>1?button('Previous',`openIncome(${js(r.month)},${js(r.type)},${r.page-1})`):''}${r.page*20<num(d.total)?button('Next',`openIncome(${js(r.month)},${js(r.type)},${r.page+1})`):''}</div>`:'');}
function pullList(type){return arr(data('pulls:'+type)?.gacha_item_list).slice().sort((a,b)=>{const aa=String(a.id??a.gacha_id??''),bb=String(b.id??b.gacha_id??'');return bb.length-aa.length||bb.localeCompare(aa);});}
function pullRarity(p){const r=p.rank_type??p.rarity??p.rank;return r==='S'||num(r)===4||num(r)===5?'S':r==='A'||num(r)===3?'A':'B';}
function pullDate(p){const d=p.date;return p.time||p.gacha_time||(d?[d.year,String(d.month).padStart(2,'0'),String(d.day).padStart(2,'0')].join('-')+' '+[d.hour,d.minute,d.second].map(x=>String(x).padStart(2,'0')).join(':'):'');}
function pullName(p){return p.name||p.item_name||p.name_mi18n||p.item?.name||'Signal result';}
function renderSignals(){const g=data('gacha'),pulls=pullList(pullType),key='pulls:'+pullType;const banners=arr(g?.gacha_info_list),info=banners.find(x=>x.gacha_type===pullType);const firstS=pulls.findIndex(x=>pullRarity(x)==='S');return `<div class="row section-head"><div><h2>Signal Search</h2><p class="meta">Banner status, saved pulls & search planning</p></div>${button('Sync history',"native('pulls')",true)}</div>${sectionMessage('gacha')}${g?`<div class="grid three">${arr(g.tickets).map(t=>`<div class="stat"><b>${fmt(t.ticket_cnt)}</b><span>${esc(ticketName(t.ticket_type))}</span></div>`).join('')}</div>`:locked('gacha','Signal Search information')}<div class="chips">${Object.entries(bannerNames).map(([k,v])=>`<button class="${pullType===k?'on':''}" onclick="pullType=${js(k)};render()">${v}</button>`).join('')}</div>${info?`<div class="panel accent"><div class="row"><h3>Guaranteed S-Rank within</h3><span class="amount">${esc(info.more_s_need_cnt)} <small class="meta">searches</small></span></div></div>`:''}${sectionMessage(key)}<div class="saved-hint">Imported history is limited to what HoYoLAB supplies. ${firstS>=0?firstS+' imported searches since the latest S-Rank.':'A complete pity count cannot be inferred from missing history.'} ${data(key)?.truncated?'Import reached its page limit; some history remains.':''}</div>${pulls.length?pulls.slice(0,250).map((p,i)=>`<div class="pull ${pullRarity(p).toLowerCase()}"><span class="rarity">${pullRarity(p)}</span><div><strong>${esc(pullName(p))}</strong><div class="meta">${esc(pullDate(p))} · ${esc(p.item_type||'')}</div></div><span class="pill">#${i+1}</span></div>`).join(''):empty('No saved Signal Search history','Connect HoYoLAB, then sync your available history. Imports merge by record ID.')}`;}
function ticketName(k){return {GACHA_TICKET_TYPE_RECHARGE_MONOCHROME:'Monochromes',GACHA_TICKET_TYPE_POLYCHROME:'Polychromes',GACHA_TICKET_TYPE_ENCRYPTED_MASTER_TAPE:'Encrypted Master Tapes',GACHA_TICKET_TYPE_MASTER_TAPE:'Master Tapes',GACHA_TICKET_TYPE_BOOPON:'Boopons'}[k]||label(k);}
function label(k){return ({first:'First priority',second:'Second priority',third:'Third priority',daily_activity_rewards:'Daily activity',growth_rewards:'Development',shiyu_rewards:'Shiyu Defense',mail_rewards:'Mail',hollow_rewards:'Hollow Zero',event_rewards:'Events',other_rewards:'Other',card_sign:'Scratch card',vitality:'Daily activity',vhs_sale:'Video store',restore:'Seconds until full',cur_point:'Current points',max_point:'Target points',num:'Count',cur_completed:'Completed',bench_state:'Crafting',shelve_state:'Temple shop',expedition_state:'Bangboo expedition',left_ts:'Seconds remaining',main_properties_4:'Slot 4 main stats',main_properties_5:'Slot 5 main stats',main_properties_6:'Slot 6 main stats',sub_properties:'Substats'}[k]||String(k).replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()));}
function scalar(v,key){if(v===true)return 'Yes';if(v===false)return 'No';if(v==null||v==='')return '—';const states={SaleStateDone:'Revenue available',SaleStateDoing:'Open for business',SaleStateNo:'Waiting to open',BenchStateCanProduce:'Ready to craft',BenchStateProducing:'Crafting',ShelveStateCanSell:'Ready to stock',ShelveStateSelling:'Selling',ShelveStateSoldOut:'Sold out',ExpeditionStateInCanSend:'Ready to dispatch',ExpeditionStateInProgress:'Exploring',ExpeditionStateEnd:'Squad returned',CardSignDone:'Collected',CardSignNo:'Not collected',CardSignNotDone:'Not collected',MemberCardStateACK:'Active',MemberCardStateNo:'Inactive'};if(states[v])return states[v];if(key==='skill_type')return skillNames[v]||v;if(key==='property_id')return propertyLabel({PropertyId:v});if(typeof v==='string'&&v.startsWith('https://'))return 'Available';return String(v);}
function inspect(v,title='',depth=0,open=false){if(depth>9)return '<p class="meta">Further details omitted.</p>';if(v===null||v===undefined)return '';if(typeof v!=='object')return `<div class="property"><span>${esc(label(title))}</span><b>${esc(scalar(v,title))}</b></div>`;const entries=Array.isArray(v)?v.map((x,i)=>[String(i+1),x]):Object.entries(v);const hidden=new Set(['id','uid','role_id','server','region','game_biz','avatar_id','weapon_id','property_id','system_id','suit_id','pos_type','icon','avatar_icon','role_square_url','group_icon_path','hollow_icon_path','role_vertical_painting_url','avatar_url','url','jump_url','background','ending_background']);const body=entries.filter(([k])=>!hidden.has(k)&&!k.includes('icon_url')).map(([k,x])=>{if(typeof x==='object'&&x!==null){const name=x.name_mi18n||x.name||x.title||(x.id&&CATALOG.avatars[String(x.id)]?nameOf(x):null);return inspect(x,name||label(k),depth+1,depth<1&&entries.length<8);}if(typeof x==='string'&&(x.includes('<')||x.length>100))return `<div class="small"><div class="meta">${esc(label(k))}</div><p class="rich">${rich(x)}</p></div>`;return inspect(x,k,depth+1);}).join('');return depth===0&&open?`<div class="detail-group">${body||'<p class="meta">No records supplied.</p>'}</div>`:`<details class="detail-group" ${open?'open':''}><summary>${esc(title||'Details')}${Array.isArray(v)?' · '+entries.length:''}</summary>${body||'<p class="meta">No records supplied.</p>'}</details>`;}
function openAccount(){modalAgent=null;const p=data('showcase')?.PlayerInfo?.SocialDetail?.ProfileDetail;modal('Your companion connection',`<div class="account-hero"><div class="eyebrow">${connected()?'CONNECTED TO HOYOLAB':p?'PUBLIC SHOWCASE CONNECTED':'CONNECT YOUR ACCOUNT'}</div><h2>${esc(p?.Nickname||'Welcome, Proxy.')}</h2><p>${p?'Inter-Knot '+esc(p.Level)+' · UID '+esc(state.uid)+' · '+esc(servers[state.server]):'Connect your ZZZ profile and bring your account to the Thor’s second screen.'}</p></div><div class="step"><b>1</b><div><strong>Public showcase</strong><p>${p?'Connected · '+publicAgents().length+' agents with equipped builds':'Enter your UID to load showcased agents.'}</p></div></div><div class="step"><b>2</b><div><strong>HoYoLAB sign-in</strong><p>Use the official web sign-in here. Signing into the separate HoYoLAB app does not connect this companion. Your validated session stays encrypted on this Thor.</p><div class="actions">${button(connected()?'Reconnect HoYoLAB':'Sign in to HoYoLAB',"native('login')",true)}${button('Account tools',"native('openTools')")}</div></div></div><div class="step"><b>3</b><div><strong>Validate your ZZZ profile</strong><p>${connected()?'Validated · your account tools are connected.':'Your session is validated before it is saved. The companion then checks your ZZZ UID and server.'}</p></div></div>${arr(state.roles).length?`<label>Profiles on signed-in HoYoLAB account</label>${arr(state.roles).map(r=>`<div class="list-row"><div><h3>${esc(r.nickname)}</h3><p class="meta">${esc(r.game_uid)} · ${esc(r.region_name||r.region)}</p></div>${button('Use profile',`native('account',${js(r.game_uid)},${js(r.region)})`)}</div>`).join('')}`:''}<div class="form-row"><div><label>ZZZ UID</label><input id="account-uid" inputmode="numeric" value="${esc(state.uid)}"></div><div><label>Server</label><select id="account-server">${Object.entries(servers).map(([k,v])=>`<option value="${k}" ${state.server===k?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="actions">${button('Use this account',"native('account',$('#account-uid').value.trim(),$('#account-server').value);closeModal()",true)}${button('Refresh connection','refreshNow()')}</div><div class="divider"></div><div class="settings-line row"><div><h3>Battery, weekly & event reminders</h3><p class="meta">Based on the latest synced status.</p></div><input type="checkbox" aria-label="Enable reminders" ${state.reminders?'checked':''} onchange="native('reminders',this.checked)"></div><p class="saved-hint">Game login and HoYoLAB login are separate. This app can validate your account data; the current combat session is not exposed by these services.</p><div class="actions">${button('Connection details','showConnections()')}${button('Disconnect HoYoLAB',"native('disconnect');closeModal()")}</div>`);}
function showConnections(){modal('Data connection details',`<p class="small">UID ${esc(state.uid)} · ${esc(servers[state.server])}</p><div class="divider"></div>${Object.entries(state.sections).map(([k,s])=>`<div class="list-row"><div><h3>${esc(label(k))}</h3><p class="meta">${esc(s.error||when(s.at))}</p></div><span class="badge">${esc(s.state)}</span></div>`).join('')}<div class="banner">Account snapshots refresh about every five minutes while this app is open. Enka requests respect the service’s refresh timer. Saved views show their age. HP, cooldowns, damage events, and live combat buffs are not supplied by these sources.</div>`);}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;selection=-1;}
function closeModal(){modalAgent=null;incomeRequest=null;$('#modal').close();selection=-1;}
function goBack(){if($('#modal').open)closeModal();else setTab('Today');}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2600);}
function focusables(){const scope=$('#modal').open?$('#modal'):$('#content');return [...scope.querySelectorAll('button,input,select,textarea,summary')].filter(el=>!el.disabled&&el.getClientRects().length);}
function moveSelection(d){const list=focusables();if(!list.length)return;$$('.selected').forEach(x=>x.classList.remove('selected'));selection=(selection+d+list.length)%list.length;list[selection].classList.add('selected');list[selection].scrollIntoView({block:'nearest'});}
function activateSelected(){const list=focusables(),el=list[Math.max(0,selection)];if(el){el.focus();if(el.tagName==='SUMMARY')el.parentElement.open=!el.parentElement.open;else el.click();}}
function scrollController(y){($('#modal').open?$('#modal'):$('#content')).scrollBy(0,y);}
setInterval(()=>{const e=$('#battery-countdown');if(e&&e.dataset.full&&num(e.dataset.full)>Date.now())e.textContent=duration((num(e.dataset.full)-Date.now())/1000)+' Until Full';else if(e&&e.dataset.full)e.textContent='Charge Update Pending';},1000);
const originalReceive=receive;receive=function(next){originalReceive(next);renderIncome();};
render();

function renderBangboos(){const list=arr(data('bangboos')?.list);return `<div class="row section-head"><div><h2>Your Bangboo</h2><p class="meta">Owned companions & development</p></div>${button('Agents',"agentKind='Agents';render()")}</div>${sectionMessage('bangboos')}${!data('bangboos')?locked('bangboos','Your Bangboo roster'):`<div class="grid">${list.map((b,i)=>`<button class="card agent" onclick="openBangboo(${i})">${img(b.icon||b.bangboo_rectangle_url||b.bangboo_square_url)}<div class="copy"><h3>${esc(b.name||b.name_mi18n||'Bangboo')}</h3><p class="meta">Lv. ${esc(b.level??'—')} · ${esc(b.rarity||'')}</p></div></button>`).join('')}</div>`}`;}
function openBangboo(i){const b=arr(data('bangboos')?.list)[i];if(b)modal(b.name||b.name_mi18n||'Bangboo',inspect(b,'Details',0,true));}
